const crypto = require('crypto');
const req = $json.body;
const headers = $json.headers;
const token = String(headers.authorization || '').replace(/^Bearer\s+/, '');
const claims = JSON.parse(Buffer.from(token.split('.')[1] || '', 'base64url').toString());
const scopes = new Set(String(claims.scope || '').split(/\s+/));
const aud = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
if (claims.azp !== 'codestra-middleware-production' || !aud.includes('codestra-n8n-production') || claims.environment !== 'production' || !scopes.has('n8n.events.submit')) throw new Error('service claims rejected');
if (!claims.business_units?.includes('BU-400-COD') || !claims.campaigns?.includes('CMP-400-COD')) throw new Error('service scope rejected');
if (req.environment !== 'production' || req.business_unit_public_id !== 'BU-400-COD' || req.campaign_public_id !== 'CMP-400-COD' || req.event_type !== 'reconciliation.run') throw new Error('event scope rejected');
if (req.attempt_number !== 1 || req.workflow?.public_id !== $workflow.id) throw new Error('workflow binding rejected');
const canonical = value => Array.isArray(value) ? `[${value.map(canonical).join(',')}]` : value && typeof value === 'object' ? `{${Object.keys(value).sort().map(k => `${JSON.stringify(k)}:${canonical(value[k])}`).join(',')}}` : JSON.stringify(value);
const sha = value => `sha256:${crypto.createHash('sha256').update(typeof value === 'string' ? value : canonical(value)).digest('hex')}`;
if (sha(req.payload) !== req.payload_hash) throw new Error('payload hash rejected');
const now = new Date().toISOString();
const registration = {
  schema_version:'1.0', registration_id:crypto.randomUUID(), delivery_id:req.delivery_id,
  event_id:req.event_id, workflow_id:$workflow.id, workflow_version:req.workflow.version,
  execution_id:$execution.id, environment:'production',
  idempotency_key:`registration:${req.delivery_id}:${$execution.id}`,
  correlation_id:req.correlation_id, payload_hash:req.payload_hash,
  request_hash:sha(req), received_at:req.recorded_at, registered_at:now
};
const raw = canonical(registration);
return [{json:{request:req, registration, registration_raw:raw, registration_headers:{'X-Codestra-Timestamp':String(Math.floor(Date.now()/1000)),'X-Codestra-Nonce':crypto.randomUUID(),'X-Codestra-Body-SHA256':sha(raw),'X-Codestra-Correlation-ID':req.correlation_id}}}];

const crypto = require('crypto');
const source = $('Validate and Build Registration').item.json;
const registered = $('Middleware Execution Registration').item.json;
const canonical = value => Array.isArray(value) ? `[${value.map(canonical).join(',')}]` : value && typeof value === 'object' ? `{${Object.keys(value).sort().map(k => `${JSON.stringify(k)}:${canonical(value[k])}`).join(',')}}` : JSON.stringify(value);
const sha = value => `sha256:${crypto.createHash('sha256').update(typeof value === 'string' ? value : canonical(value)).digest('hex')}`;
const now = new Date().toISOString();
const result = {operation:'reconciliation.run',mode:'internal-report-only',test_run_id:source.request.payload.test_run_id};
const acknowledgement = {schema_version:'1.0',acknowledgement_id:crypto.randomUUID(),registration_id:registered.registration_id,delivery_id:source.request.delivery_id,event_id:source.request.event_id,workflow_id:$workflow.id,workflow_version:source.request.workflow.version,execution_id:$execution.id,execution_status:'SUCCEEDED',result_classification:'RECONCILIATION_COMPLETE',result_hash:sha(result),attempt_number:1,correlation_id:source.request.correlation_id,policy_hash:source.request.policy.hash,started_at:source.registration.registered_at,completed_at:now,metrics:{duration_ms:Math.max(0,Date.now()-Date.parse(source.registration.registered_at))}};
const raw = canonical(acknowledgement);
return [{json:{acknowledgement,acknowledgement_raw:raw,acknowledgement_headers:{'X-Codestra-Timestamp':String(Math.floor(Date.now()/1000)),'X-Codestra-Nonce':crypto.randomUUID(),'X-Codestra-Body-SHA256':sha(raw),'X-Codestra-Correlation-ID':source.request.correlation_id}}}];
